insert into public.ui_strings (key, section, description, draft_value, published_value, sort) values ('hero.sub', 'Homepage — Hero', null, '{"en":"Real conversation, real culture — not grammar drills. Master Kriolu, English, French, Spanish or Portuguese with teachers who live the language.","pt":"Conversa real, cultura real — não exercícios de gramática. Domina Kriolu, Inglês, Francês, Espanhol ou Português com professores que vivem a língua.","fr":"De vraies conversations, une vraie culture — pas des exercices de grammaire. Maîtrise le créole, l''anglais, le français, l''espagnol ou le portugais avec des professeurs qui vivent la langue.","es":"Conversación real, cultura real — no ejercicios de gramática. Domina el criollo, inglés, francés, español o portugués con profesores que viven el idioma.","kr":"Konbersu di verdadi, kultura di verdadi — ka izersísiu di gramátika. Domina Kriolu, Inglês, Fransês, Spanhol ô Portugês ku profesoris ki ta vive língua."}'::jsonb, '{"en":"Real conversation, real culture — not grammar drills. Master Kriolu, English, French, Spanish or Portuguese with teachers who live the language.","pt":"Conversa real, cultura real — não exercícios de gramática. Domina Kriolu, Inglês, Francês, Espanhol ou Português com professores que vivem a língua.","fr":"De vraies conversations, une vraie culture — pas des exercices de grammaire. Maîtrise le créole, l''anglais, le français, l''espagnol ou le portugais avec des professeurs qui vivent la langue.","es":"Conversación real, cultura real — no ejercicios de gramática. Domina el criollo, inglés, francés, español o portugués con profesores que viven el idioma.","kr":"Konbersu di verdadi, kultura di verdadi — ka izersísiu di gramátika. Domina Kriolu, Inglês, Fransês, Spanhol ô Portugês ku profesoris ki ta vive língua."}'::jsonb, 10) on conflict (key) do nothing;
