insert into public.ui_strings (key, section, description, draft_value, published_value, sort) values ('langs.sub', 'Homepage — Languages', null, '{"en":"Each taught by someone who lives it — with the slang, the rhythm and the warmth of real Cape Verdean hospitality.","pt":"Cada uma ensinada por alguém que a vive — com a gíria, o ritmo e o calor da verdadeira hospitalidade cabo-verdiana.","fr":"Chacune enseignée par quelqu''un qui la vit — avec l''argot, le rythme et la chaleur de la vraie hospitalité cap-verdienne.","es":"Cada uno enseñado por alguien que lo vive — con la jerga, el ritmo y la calidez de la verdadera hospitalidad caboverdiana.","kr":"Kada un insinadu pa algen ki ta vive-l — ku gíria, ritmu i kalor di verdaderu ospitalidadi kabu-verdianu."}'::jsonb, '{"en":"Each taught by someone who lives it — with the slang, the rhythm and the warmth of real Cape Verdean hospitality.","pt":"Cada uma ensinada por alguém que a vive — com a gíria, o ritmo e o calor da verdadeira hospitalidade cabo-verdiana.","fr":"Chacune enseignée par quelqu''un qui la vit — avec l''argot, le rythme et la chaleur de la vraie hospitalité cap-verdienne.","es":"Cada uno enseñado por alguien que lo vive — con la jerga, el ritmo y la calidez de la verdadera hospitalidad caboverdiana.","kr":"Kada un insinadu pa algen ki ta vive-l — ku gíria, ritmu i kalor di verdaderu ospitalidadi kabu-verdianu."}'::jsonb, 35) on conflict (key) do nothing;
