insert into public.ui_strings (key, section, description, draft_value, published_value, sort) values ('live.sub', 'Homepage — Learn live', null, '{"en":"Sit across from a native speaker — online or in person — and actually talk. Classes are built around you, your goals and the culture you''re stepping into.","pt":"Senta-te frente a um falante nativo — online ou presencial — e fala de verdade. As aulas são feitas à tua volta, dos teus objetivos e da cultura em que estás a entrar.","fr":"Assieds-toi face à un locuteur natif — en ligne ou en personne — et parle vraiment. Les cours sont construits autour de toi, de tes objectifs et de la culture que tu découvres.","es":"Siéntate frente a un hablante nativo — en línea o en persona — y habla de verdad. Las clases se construyen en torno a ti, tus objetivos y la cultura en la que entras.","kr":"Senta na frenti di un falanti nativu — online ô prezensial — i papia di verdadi. Aula é feitu pa bo, pa bu objetivu i pa kultura ki bu sta entra."}'::jsonb, '{"en":"Sit across from a native speaker — online or in person — and actually talk. Classes are built around you, your goals and the culture you''re stepping into.","pt":"Senta-te frente a um falante nativo — online ou presencial — e fala de verdade. As aulas são feitas à tua volta, dos teus objetivos e da cultura em que estás a entrar.","fr":"Assieds-toi face à un locuteur natif — en ligne ou en personne — et parle vraiment. Les cours sont construits autour de toi, de tes objectifs et de la culture que tu découvres.","es":"Siéntate frente a un hablante nativo — en línea o en persona — y habla de verdad. Las clases se construyen en torno a ti, tus objetivos y la cultura en la que entras.","kr":"Senta na frenti di un falanti nativu — online ô prezensial — i papia di verdadi. Aula é feitu pa bo, pa bu objetivu i pa kultura ki bu sta entra."}'::jsonb, 46) on conflict (key) do nothing;
