insert into public.ui_strings (key, section, description, draft_value, published_value, sort) values ('any.sub', 'Homepage — Anytime anywhere', null, '{"en":"Join a class from Praia or Paris. Pick up where you left off on any device, with lessons, vocabulary and culture always in your pocket.","pt":"Entra numa aula desde a Praia ou Paris. Continua de onde paraste em qualquer dispositivo, com lições, vocabulário e cultura sempre no teu bolso.","fr":"Rejoins un cours depuis Praia ou Paris. Reprends où tu t''es arrêté sur n''importe quel appareil, avec leçons, vocabulaire et culture toujours dans ta poche.","es":"Únete a una clase desde Praia o París. Retoma donde lo dejaste en cualquier dispositivo, con lecciones, vocabulario y cultura siempre en tu bolsillo.","kr":"Djunta na un aula désdi Praia ô Paris. Kontinua undi ki bu para na kalker dispozitivu, ku lisãu, vokabuláriu i kultura sénpri na bu bolsu."}'::jsonb, '{"en":"Join a class from Praia or Paris. Pick up where you left off on any device, with lessons, vocabulary and culture always in your pocket.","pt":"Entra numa aula desde a Praia ou Paris. Continua de onde paraste em qualquer dispositivo, com lições, vocabulário e cultura sempre no teu bolso.","fr":"Rejoins un cours depuis Praia ou Paris. Reprends où tu t''es arrêté sur n''importe quel appareil, avec leçons, vocabulaire et culture toujours dans ta poche.","es":"Únete a una clase desde Praia o París. Retoma donde lo dejaste en cualquier dispositivo, con lecciones, vocabulario y cultura siempre en tu bolsillo.","kr":"Djunta na un aula désdi Praia ô Paris. Kontinua undi ki bu para na kalker dispozitivu, ku lisãu, vokabuláriu i kultura sénpri na bu bolsu."}'::jsonb, 53) on conflict (key) do nothing;
