insert into public.ui_strings (key, section, description, draft_value, published_value, sort) values ('cta.sub', 'Homepage — Call to action', null, '{"en":"Create a free account, take a 60-second placement test, or book a trial class with a native teacher.","pt":"Cria uma conta grátis, faz um teste de nível de 60 segundos, ou marca uma aula experimental com um professor nativo.","fr":"Crée un compte gratuit, passe un test de niveau de 60 secondes, ou réserve un cours d''essai avec un professeur natif.","es":"Crea una cuenta gratis, haz una prueba de nivel de 60 segundos, o reserva una clase de prueba con un profesor nativo.","kr":"Kria un konta gratis, fazi un tésti di nível di 60 segundu, ô marka un aula ku un profesor nativu."}'::jsonb, '{"en":"Create a free account, take a 60-second placement test, or book a trial class with a native teacher.","pt":"Cria uma conta grátis, faz um teste de nível de 60 segundos, ou marca uma aula experimental com um professor nativo.","fr":"Crée un compte gratuit, passe un test de niveau de 60 secondes, ou réserve un cours d''essai avec un professeur natif.","es":"Crea una cuenta gratis, haz una prueba de nivel de 60 segundos, o reserva una clase de prueba con un profesor nativo.","kr":"Kria un konta gratis, fazi un tésti di nível di 60 segundu, ô marka un aula ku un profesor nativu."}'::jsonb, 62) on conflict (key) do nothing;
