insert into public.ui_strings (key, section, description, draft_value, published_value, sort) values ('foot.tagline', 'Footer', null, '{"en":"A language school born in Cabo Verde, teaching the world to speak with heart. Learn Kriolu, English, French, Spanish and Portuguese with native speakers — online or in person.","pt":"Uma escola de línguas nascida em Cabo Verde, a ensinar o mundo a falar com o coração. Aprende Kriolu, Inglês, Francês, Espanhol e Português com falantes nativos — online ou presencial.","fr":"Une école de langues née au Cap-Vert, qui apprend au monde à parler avec le cœur. Apprends le créole, l''anglais, le français, l''espagnol et le portugais avec des natifs — en ligne ou en personne.","es":"Una escuela de idiomas nacida en Cabo Verde, que enseña al mundo a hablar con el corazón. Aprende criollo, inglés, francés, español y portugués con hablantes nativos — en línea o en persona.","kr":"Un skola di língua ki nasi na Kabu Verdi, ta insina mundu papia ku korasãu. Aprende Kriolu, Inglês, Fransês, Spanhol i Portugês ku falanti nativu — online ô prezensial."}'::jsonb, '{"en":"A language school born in Cabo Verde, teaching the world to speak with heart. Learn Kriolu, English, French, Spanish and Portuguese with native speakers — online or in person.","pt":"Uma escola de línguas nascida em Cabo Verde, a ensinar o mundo a falar com o coração. Aprende Kriolu, Inglês, Francês, Espanhol e Português com falantes nativos — online ou presencial.","fr":"Une école de langues née au Cap-Vert, qui apprend au monde à parler avec le cœur. Apprends le créole, l''anglais, le français, l''espagnol et le portugais avec des natifs — en ligne ou en personne.","es":"Una escuela de idiomas nacida en Cabo Verde, que enseña al mundo a hablar con el corazón. Aprende criollo, inglés, francés, español y portugués con hablantes nativos — en línea o en persona.","kr":"Un skola di língua ki nasi na Kabu Verdi, ta insina mundu papia ku korasãu. Aprende Kriolu, Inglês, Fransês, Spanhol i Portugês ku falanti nativu — online ô prezensial."}'::jsonb, 65) on conflict (key) do nothing;
