insert into public.ui_strings (key, section, description, draft_value, published_value, sort) values ('about.intro', 'About page', null, '{"en":"IClangues began with a simple idea: the best way to learn a language is from someone who lives it. From a small classroom in Cabo Verde, we now teach learners across continents — keeping every lesson full of culture, music and morabeza.","pt":"A IClangues começou com uma ideia simples: a melhor forma de aprender uma língua é com alguém que a vive. De uma pequena sala em Cabo Verde, ensinamos agora alunos em vários continentes — mantendo cada aula cheia de cultura, música e morabeza.","fr":"IClangues est née d''une idée simple : la meilleure façon d''apprendre une langue, c''est auprès de quelqu''un qui la vit. D''une petite salle de classe au Cap-Vert, nous enseignons aujourd''hui à des apprenants sur plusieurs continents — en gardant chaque cours plein de culture, de musique et de morabeza.","es":"IClangues comenzó con una idea simple: la mejor forma de aprender un idioma es de alguien que lo vive. Desde una pequeña aula en Cabo Verde, ahora enseñamos a estudiantes en varios continentes — manteniendo cada clase llena de cultura, música y morabeza.","kr":"IClangues komesa ku un ideia simplis: midjor manera di aprende un língua é ku algen ki ta vive-l. Désdi un sala pikinoti na Kabu Verdi, gósi nu ta insina alunu na vários kontinenti — ta mante kada aula xeiu di kultura, múzika i morabeza."}'::jsonb, '{"en":"IClangues began with a simple idea: the best way to learn a language is from someone who lives it. From a small classroom in Cabo Verde, we now teach learners across continents — keeping every lesson full of culture, music and morabeza.","pt":"A IClangues começou com uma ideia simples: a melhor forma de aprender uma língua é com alguém que a vive. De uma pequena sala em Cabo Verde, ensinamos agora alunos em vários continentes — mantendo cada aula cheia de cultura, música e morabeza.","fr":"IClangues est née d''une idée simple : la meilleure façon d''apprendre une langue, c''est auprès de quelqu''un qui la vit. D''une petite salle de classe au Cap-Vert, nous enseignons aujourd''hui à des apprenants sur plusieurs continents — en gardant chaque cours plein de culture, de musique et de morabeza.","es":"IClangues comenzó con una idea simple: la mejor forma de aprender un idioma es de alguien que lo vive. Desde una pequeña aula en Cabo Verde, ahora enseñamos a estudiantes en varios continentes — manteniendo cada clase llena de cultura, música y morabeza.","kr":"IClangues komesa ku un ideia simplis: midjor manera di aprende un língua é ku algen ki ta vive-l. Désdi un sala pikinoti na Kabu Verdi, gósi nu ta insina alunu na vários kontinenti — ta mante kada aula xeiu di kultura, múzika i morabeza."}'::jsonb, 76) on conflict (key) do nothing;
insert into public.ui_strings (key, section, description, draft_value, published_value, sort) values ('about.h2', 'About page', null, '{"en":"Language is connection. We teach the connection.","pt":"A língua é conexão. Nós ensinamos a conexão.","fr":"La langue, c''est le lien. Nous enseignons ce lien.","es":"El idioma es conexión. Nosotros enseñamos la conexión.","kr":"Língua é konexãu. Nu ta insina konexãu."}'::jsonb, '{"en":"Language is connection. We teach the connection.","pt":"A língua é conexão. Nós ensinamos a conexão.","fr":"La langue, c''est le lien. Nous enseignons ce lien.","es":"El idioma es conexión. Nosotros enseñamos la conexión.","kr":"Língua é konexãu. Nu ta insina konexãu."}'::jsonb, 77) on conflict (key) do nothing;
insert into public.ui_strings (key, section, description, draft_value, published_value, sort) values ('about.body', 'About page', null, '{"en":"At IClangues we don''t just deliver lessons — we share a way of speaking, listening and being. Founded in Cabo Verde, our team of native-speaking teachers brings together five languages we love: Kriolu, Português, English, Français and Español. Whether you''re an expat learning to chat with neighbours or a professional preparing for global work, we meet you where you are.","pt":"Na IClangues não damos apenas aulas — partilhamos uma forma de falar, ouvir e ser. Fundada em Cabo Verde, a nossa equipa de professores nativos reúne cinco línguas que adoramos: Kriolu, Português, Inglês, Francês e Espanhol. Quer sejas um expatriado a aprender a conversar com os vizinhos ou um profissional a preparar-se para o trabalho global, encontramos-te onde estás.","fr":"Chez IClangues, nous ne donnons pas que des cours — nous partageons une façon de parler, d''écouter et d''être. Fondée au Cap-Vert, notre équipe de professeurs natifs réunit cinq langues que nous aimons : créole, portugais, anglais, français et espagnol. Que tu sois un expatrié apprenant à discuter avec tes voisins ou un professionnel se préparant au travail international, nous te rejoignons là où tu es.","es":"En IClangues no solo damos clases — compartimos una forma de hablar, escuchar y ser. Fundada en Cabo Verde, nuestro equipo de profesores nativos reúne cinco idiomas que amamos: criollo, portugués, inglés, francés y español. Ya seas un expatriado aprendiendo a charlar con los vecinos o un profesional preparándose para el trabajo global, te encontramos donde estás.","kr":"Na IClangues nu ka ta da sô aula — nu ta partilha un manera di papia, obi i ser. Fundadu na Kabu Verdi, nos ekipa di profesor nativu ta djunta sinku língua ki nu ama: Kriolu, Portugês, Inglês, Fransês i Spanhol. Si bu é un strandjeru ta aprende konversa ku bizinhu ô un profisional ta prepara pa trabadju global, nu ta atxa-u undi ki bu sta."}'::jsonb, '{"en":"At IClangues we don''t just deliver lessons — we share a way of speaking, listening and being. Founded in Cabo Verde, our team of native-speaking teachers brings together five languages we love: Kriolu, Português, English, Français and Español. Whether you''re an expat learning to chat with neighbours or a professional preparing for global work, we meet you where you are.","pt":"Na IClangues não damos apenas aulas — partilhamos uma forma de falar, ouvir e ser. Fundada em Cabo Verde, a nossa equipa de professores nativos reúne cinco línguas que adoramos: Kriolu, Português, Inglês, Francês e Espanhol. Quer sejas um expatriado a aprender a conversar com os vizinhos ou um profissional a preparar-se para o trabalho global, encontramos-te onde estás.","fr":"Chez IClangues, nous ne donnons pas que des cours — nous partageons une façon de parler, d''écouter et d''être. Fondée au Cap-Vert, notre équipe de professeurs natifs réunit cinq langues que nous aimons : créole, portugais, anglais, français et espagnol. Que tu sois un expatrié apprenant à discuter avec tes voisins ou un professionnel se préparant au travail international, nous te rejoignons là où tu es.","es":"En IClangues no solo damos clases — compartimos una forma de hablar, escuchar y ser. Fundada en Cabo Verde, nuestro equipo de profesores nativos reúne cinco idiomas que amamos: criollo, portugués, inglés, francés y español. Ya seas un expatriado aprendiendo a charlar con los vecinos o un profesional preparándose para el trabajo global, te encontramos donde estás.","kr":"Na IClangues nu ka ta da sô aula — nu ta partilha un manera di papia, obi i ser. Fundadu na Kabu Verdi, nos ekipa di profesor nativu ta djunta sinku língua ki nu ama: Kriolu, Portugês, Inglês, Fransês i Spanhol. Si bu é un strandjeru ta aprende konversa ku bizinhu ô un profisional ta prepara pa trabadju global, nu ta atxa-u undi ki bu sta."}'::jsonb, 78) on conflict (key) do nothing;
