insert into public.ui_strings (key, section, description, draft_value, published_value, sort) values ('about.v1.text', 'About page', null, '{"en":"Cape Verdean warmth — the way we welcome every learner, from beginner to advanced.","pt":"O calor cabo-verdiano — a forma como acolhemos cada aluno, do iniciante ao avançado.","fr":"La chaleur cap-verdienne — notre façon d''accueillir chaque apprenant, du débutant à l''avancé.","es":"La calidez caboverdiana — la forma en que acogemos a cada estudiante, del principiante al avanzado.","kr":"Kalor kabu-verdianu — manera ki nu ta resebe kada alunu, di iniciante te avansadu."}'::jsonb, '{"en":"Cape Verdean warmth — the way we welcome every learner, from beginner to advanced.","pt":"O calor cabo-verdiano — a forma como acolhemos cada aluno, do iniciante ao avançado.","fr":"La chaleur cap-verdienne — notre façon d''accueillir chaque apprenant, du débutant à l''avancé.","es":"La calidez caboverdiana — la forma en que acogemos a cada estudiante, del principiante al avanzado.","kr":"Kalor kabu-verdianu — manera ki nu ta resebe kada alunu, di iniciante te avansadu."}'::jsonb, 82) on conflict (key) do nothing;
insert into public.ui_strings (key, section, description, draft_value, published_value, sort) values ('about.v2.title', 'About page', null, '{"en":"Native voices","pt":"Vozes nativas","fr":"Voix natives","es":"Voces nativas","kr":"Vós nativu"}'::jsonb, '{"en":"Native voices","pt":"Vozes nativas","fr":"Voix natives","es":"Voces nativas","kr":"Vós nativu"}'::jsonb, 83) on conflict (key) do nothing;
insert into public.ui_strings (key, section, description, draft_value, published_value, sort) values ('about.v2.text', 'About page', null, '{"en":"Our teachers don''t translate culture. They live it.","pt":"Os nossos professores não traduzem a cultura. Eles vivem-na.","fr":"Nos professeurs ne traduisent pas la culture. Ils la vivent.","es":"Nuestros profesores no traducen la cultura. La viven.","kr":"Nos profesor ka ta traduzi kultura. Es ta vive-l."}'::jsonb, '{"en":"Our teachers don''t translate culture. They live it.","pt":"Os nossos professores não traduzem a cultura. Eles vivem-na.","fr":"Nos professeurs ne traduisent pas la culture. Ils la vivent.","es":"Nuestros profesores no traducen la cultura. La viven.","kr":"Nos profesor ka ta traduzi kultura. Es ta vive-l."}'::jsonb, 84) on conflict (key) do nothing;
insert into public.ui_strings (key, section, description, draft_value, published_value, sort) values ('about.v3.title', 'About page', null, '{"en":"Local & global","pt":"Local e global","fr":"Local et global","es":"Local y global","kr":"Lokal i global"}'::jsonb, '{"en":"Local & global","pt":"Local e global","fr":"Local et global","es":"Local y global","kr":"Lokal i global"}'::jsonb, 85) on conflict (key) do nothing;
insert into public.ui_strings (key, section, description, draft_value, published_value, sort) values ('about.v3.text', 'About page', null, '{"en":"Rooted in Cabo Verde, open to the world. Online classes connect islanders and learners everywhere.","pt":"Enraizada em Cabo Verde, aberta ao mundo. As aulas online ligam ilhéus e alunos de toda a parte.","fr":"Enracinée au Cap-Vert, ouverte au monde. Les cours en ligne relient les insulaires et les apprenants du monde entier.","es":"Arraigada en Cabo Verde, abierta al mundo. Las clases online conectan a isleños y estudiantes de todas partes.","kr":"Ku raís na Kabu Verdi, abértu pa mundu. Aula online ta liga ilheu i alunu di tudu ladu."}'::jsonb, '{"en":"Rooted in Cabo Verde, open to the world. Online classes connect islanders and learners everywhere.","pt":"Enraizada em Cabo Verde, aberta ao mundo. As aulas online ligam ilhéus e alunos de toda a parte.","fr":"Enracinée au Cap-Vert, ouverte au monde. Les cours en ligne relient les insulaires et les apprenants du monde entier.","es":"Arraigada en Cabo Verde, abierta al mundo. Las clases online conectan a isleños y estudiantes de todas partes.","kr":"Ku raís na Kabu Verdi, abértu pa mundu. Aula online ta liga ilheu i alunu di tudu ladu."}'::jsonb, 86) on conflict (key) do nothing;
insert into public.ui_strings (key, section, description, draft_value, published_value, sort) values ('about.v4.title', 'About page', null, '{"en":"Real conversation","pt":"Conversa real","fr":"Vraie conversation","es":"Conversación real","kr":"Konbersu real"}'::jsonb, '{"en":"Real conversation","pt":"Conversa real","fr":"Vraie conversation","es":"Conversación real","kr":"Konbersu real"}'::jsonb, 87) on conflict (key) do nothing;
insert into public.ui_strings (key, section, description, draft_value, published_value, sort) values ('about.v4.text', 'About page', null, '{"en":"Forget rote drills. We learn the way people actually speak — with rhythm, slang and feeling.","pt":"Esquece os exercícios decorados. Aprendemos como as pessoas falam de verdade — com ritmo, gíria e sentimento.","fr":"Oublie les exercices par cœur. On apprend comme les gens parlent vraiment — avec rythme, argot et émotion.","es":"Olvida los ejercicios de memoria. Aprendemos como la gente habla de verdad — con ritmo, jerga y sentimiento.","kr":"Skese izersísiu di kor. Nu ta aprende manera ki algen ta papia di verdadi — ku ritmu, gíria i sentimentu."}'::jsonb, '{"en":"Forget rote drills. We learn the way people actually speak — with rhythm, slang and feeling.","pt":"Esquece os exercícios decorados. Aprendemos como as pessoas falam de verdade — com ritmo, gíria e sentimento.","fr":"Oublie les exercices par cœur. On apprend comme les gens parlent vraiment — avec rythme, argot et émotion.","es":"Olvida los ejercicios de memoria. Aprendemos como la gente habla de verdad — con ritmo, jerga y sentimiento.","kr":"Skese izersísiu di kor. Nu ta aprende manera ki algen ta papia di verdadi — ku ritmu, gíria i sentimentu."}'::jsonb, 88) on conflict (key) do nothing;
insert into public.ui_strings (key, section, description, draft_value, published_value, sort) values ('about.people.heading', 'About page', null, '{"en":"People before pedagogy","pt":"Pessoas antes da pedagogia","fr":"L''humain avant la pédagogie","es":"Las personas antes que la pedagogía","kr":"Algen antis di pedagojia"}'::jsonb, '{"en":"People before pedagogy","pt":"Pessoas antes da pedagogia","fr":"L''humain avant la pédagogie","es":"Las personas antes que la pedagogía","kr":"Algen antis di pedagojia"}'::jsonb, 89) on conflict (key) do nothing;
insert into public.ui_strings (key, section, description, draft_value, published_value, sort) values ('about.people.text', 'About page', null, '{"en":"Every IClangues teacher is a native speaker — selected for warmth, patience and a love for sharing their culture. Kriolu teachers from Santiago and São Vicente, Portuguese teachers trained in CEFR methodology, bilingual French teachers, and English and Spanish teachers from across the world.","pt":"Cada professor da IClangues é falante nativo — escolhido pela simpatia, paciência e amor por partilhar a sua cultura. Professores de Kriolu de Santiago e São Vicente, professores de Português formados na metodologia CEFR, professores de Francês bilingues, e professores de Inglês e Espanhol de todo o mundo.","fr":"Chaque professeur IClangues est un locuteur natif — choisi pour sa chaleur, sa patience et son amour du partage de sa culture. Des professeurs de créole de Santiago et São Vicente, des professeurs de portugais formés à la méthodologie CECR, des professeurs de français bilingues, et des professeurs d''anglais et d''espagnol du monde entier.","es":"Cada profesor de IClangues es hablante nativo — elegido por su calidez, paciencia y amor por compartir su cultura. Profesores de criollo de Santiago y São Vicente, profesores de portugués formados en la metodología MCER, profesores de francés bilingües, y profesores de inglés y español de todo el mundo.","kr":"Kada profesor di IClangues é falanti nativu — skodjedu pa se kalor, pasénsia i amor di partilha se kultura. Profesor di Kriolu di Santiagu i São Visenti, profesor di Portugês formadu na metodolojia CEFR, profesor di Fransês bilíngui, i profesor di Inglês i Spanhol di tudu mundu."}'::jsonb, '{"en":"Every IClangues teacher is a native speaker — selected for warmth, patience and a love for sharing their culture. Kriolu teachers from Santiago and São Vicente, Portuguese teachers trained in CEFR methodology, bilingual French teachers, and English and Spanish teachers from across the world.","pt":"Cada professor da IClangues é falante nativo — escolhido pela simpatia, paciência e amor por partilhar a sua cultura. Professores de Kriolu de Santiago e São Vicente, professores de Português formados na metodologia CEFR, professores de Francês bilingues, e professores de Inglês e Espanhol de todo o mundo.","fr":"Chaque professeur IClangues est un locuteur natif — choisi pour sa chaleur, sa patience et son amour du partage de sa culture. Des professeurs de créole de Santiago et São Vicente, des professeurs de portugais formés à la méthodologie CECR, des professeurs de français bilingues, et des professeurs d''anglais et d''espagnol du monde entier.","es":"Cada profesor de IClangues es hablante nativo — elegido por su calidez, paciencia y amor por compartir su cultura. Profesores de criollo de Santiago y São Vicente, profesores de portugués formados en la metodología MCER, profesores de francés bilingües, y profesores de inglés y español de todo el mundo.","kr":"Kada profesor di IClangues é falanti nativu — skodjedu pa se kalor, pasénsia i amor di partilha se kultura. Profesor di Kriolu di Santiagu i São Visenti, profesor di Portugês formadu na metodolojia CEFR, profesor di Fransês bilíngui, i profesor di Inglês i Spanhol di tudu mundu."}'::jsonb, 90) on conflict (key) do nothing;
insert into public.ui_strings (key, section, description, draft_value, published_value, sort) values ('about.cta1', 'About page', null, '{"en":"Meet us & book a class","pt":"Conhece-nos e marca uma aula","fr":"Rencontre-nous et réserve un cours","es":"Conócenos y reserva una clase","kr":"Konxe-nu i marka un aula"}'::jsonb, '{"en":"Meet us & book a class","pt":"Conhece-nos e marca uma aula","fr":"Rencontre-nous et réserve un cours","es":"Conócenos y reserva una clase","kr":"Konxe-nu i marka un aula"}'::jsonb, 91) on conflict (key) do nothing;
