insert into public.ui_strings (key, section, description, draft_value, published_value, sort) values ('contact.eyebrow', 'Contact page', null, '{"en":"Get in touch","pt":"Entra em contacto","fr":"Contacte-nous","es":"Ponte en contacto","kr":"Entra en kontaktu"}'::jsonb, '{"en":"Get in touch","pt":"Entra em contacto","fr":"Contacte-nous","es":"Ponte en contacto","kr":"Entra en kontaktu"}'::jsonb, 93) on conflict (key) do nothing;
insert into public.ui_strings (key, section, description, draft_value, published_value, sort) values ('contact.sub', 'Contact page', null, '{"en":"However you say hello — we''re listening. Reach out to book a free trial class, ask about courses, or just say bo dia.","pt":"Seja como for que dizes olá — estamos a ouvir. Contacta-nos para marcar uma aula experimental grátis, perguntar sobre cursos, ou só dizer bo dia.","fr":"Quelle que soit la façon dont tu dis bonjour — nous t''écoutons. Contacte-nous pour réserver un cours d''essai gratuit, poser des questions sur les cours, ou simplement dire bo dia.","es":"Como sea que digas hola — te escuchamos. Escríbenos para reservar una clase de prueba gratis, preguntar sobre cursos, o solo decir bo dia.","kr":"Di kalker manera ki bu ta fla olá — nu sta ta obi. Entra en kontaktu pa marka un aula gratis, pergunta sobri kursu, ô sô fla bo dia."}'::jsonb, '{"en":"However you say hello — we''re listening. Reach out to book a free trial class, ask about courses, or just say bo dia.","pt":"Seja como for que dizes olá — estamos a ouvir. Contacta-nos para marcar uma aula experimental grátis, perguntar sobre cursos, ou só dizer bo dia.","fr":"Quelle que soit la façon dont tu dis bonjour — nous t''écoutons. Contacte-nous pour réserver un cours d''essai gratuit, poser des questions sur les cours, ou simplement dire bo dia.","es":"Como sea que digas hola — te escuchamos. Escríbenos para reservar una clase de prueba gratis, preguntar sobre cursos, o solo decir bo dia.","kr":"Di kalker manera ki bu ta fla olá — nu sta ta obi. Entra en kontaktu pa marka un aula gratis, pergunta sobri kursu, ô sô fla bo dia."}'::jsonb, 94) on conflict (key) do nothing;
