insert into public.ui_strings (key, section, description, draft_value, published_value, sort) values ('contact.whatsappMsg', 'Contact page', null, '{"en":"Message us — replies within an hour","pt":"Escreve-nos — respondemos dentro de uma hora","fr":"Écris-nous — réponse en moins d''une heure","es":"Escríbenos — respondemos en menos de una hora","kr":"Skrebe-nu — nu ta responde déntru di un ora"}'::jsonb, '{"en":"Message us — replies within an hour","pt":"Escreve-nos — respondemos dentro de uma hora","fr":"Écris-nous — réponse en moins d''une heure","es":"Escríbenos — respondemos en menos de una hora","kr":"Skrebe-nu — nu ta responde déntru di un ora"}'::jsonb, 97) on conflict (key) do nothing;
