insert into public.ui_strings (key, section, description, draft_value, published_value, sort) values ('cform.reply', 'Contact form', null, '{"en":"We reply within one working day. No spam, ever.","pt":"Respondemos dentro de um dia útil. Sem spam, nunca.","fr":"Nous répondons sous un jour ouvrable. Jamais de spam.","es":"Respondemos en un día hábil. Sin spam, nunca.","kr":"Nu ta responde déntru di un dia útil. Nunka spam."}'::jsonb, '{"en":"We reply within one working day. No spam, ever.","pt":"Respondemos dentro de um dia útil. Sem spam, nunca.","fr":"Nous répondons sous un jour ouvrable. Jamais de spam.","es":"Respondemos en un día hábil. Sin spam, nunca.","kr":"Nu ta responde déntru di un dia útil. Nunka spam."}'::jsonb, 106) on conflict (key) do nothing;
insert into public.ui_strings (key, section, description, draft_value, published_value, sort) values ('cform.errName', 'Contact form', null, '{"en":"Please enter your name.","pt":"Por favor, escreve o teu nome.","fr":"Merci d''indiquer ton nom.","es":"Por favor, escribe tu nombre.","kr":"Pur favor, skrebe bu nomi."}'::jsonb, '{"en":"Please enter your name.","pt":"Por favor, escreve o teu nome.","fr":"Merci d''indiquer ton nom.","es":"Por favor, escribe tu nombre.","kr":"Pur favor, skrebe bu nomi."}'::jsonb, 107) on conflict (key) do nothing;
insert into public.ui_strings (key, section, description, draft_value, published_value, sort) values ('cform.errEmail', 'Contact form', null, '{"en":"Enter a valid email.","pt":"Escreve um email válido.","fr":"Entre un email valide.","es":"Escribe un correo válido.","kr":"Skrebe un email válidu."}'::jsonb, '{"en":"Enter a valid email.","pt":"Escreve um email válido.","fr":"Entre un email valide.","es":"Escribe un correo válido.","kr":"Skrebe un email válidu."}'::jsonb, 108) on conflict (key) do nothing;
insert into public.ui_strings (key, section, description, draft_value, published_value, sort) values ('cform.errMsg', 'Contact form', null, '{"en":"Please add a short message.","pt":"Por favor, adiciona uma mensagem curta.","fr":"Ajoute un court message.","es":"Por favor, añade un mensaje corto.","kr":"Pur favor, adisiona un mensajen kurtu."}'::jsonb, '{"en":"Please add a short message.","pt":"Por favor, adiciona uma mensagem curta.","fr":"Ajoute un court message.","es":"Por favor, añade un mensaje corto.","kr":"Pur favor, adisiona un mensajen kurtu."}'::jsonb, 109) on conflict (key) do nothing;
insert into public.ui_strings (key, section, description, draft_value, published_value, sort) values ('cform.sentTitle', 'Contact form', null, '{"en":"Obrigadu! Message sent.","pt":"Obrigadu! Mensagem enviada.","fr":"Obrigadu ! Message envoyé.","es":"¡Obrigadu! Mensaje enviado.","kr":"Obrigadu! Mensajen mandadu."}'::jsonb, '{"en":"Obrigadu! Message sent.","pt":"Obrigadu! Mensagem enviada.","fr":"Obrigadu ! Message envoyé.","es":"¡Obrigadu! Mensaje enviado.","kr":"Obrigadu! Mensajen mandadu."}'::jsonb, 110) on conflict (key) do nothing;
insert into public.ui_strings (key, section, description, draft_value, published_value, sort) values ('cform.sentBody', 'Contact form', null, '{"en":"We''ll be in touch very soon to start your journey.","pt":"Entraremos em contacto muito em breve para começar a tua jornada.","fr":"Nous te contacterons très bientôt pour commencer ton parcours.","es":"Nos pondremos en contacto muy pronto para comenzar tu viaje.","kr":"Nu ta entra en kontaktu mutu sedu pa komesa bu jornada."}'::jsonb, '{"en":"We''ll be in touch very soon to start your journey.","pt":"Entraremos em contacto muito em breve para começar a tua jornada.","fr":"Nous te contacterons très bientôt pour commencer ton parcours.","es":"Nos pondremos en contacto muy pronto para comenzar tu viaje.","kr":"Nu ta entra en kontaktu mutu sedu pa komesa bu jornada."}'::jsonb, 111) on conflict (key) do nothing;
