insert into public.nav_items (menu, label, href, sort) select 'header', '{"en":"About","pt":"Sobre","fr":"À propos","es":"Nosotros","kr":"Sobri"}'::jsonb, '/about', 0 where not exists (select 1 from public.nav_items where menu = 'header' and href = '/about');
insert into public.nav_items (menu, label, href, sort) select 'header', '{"en":"Contact","pt":"Contacto","fr":"Contact","es":"Contacto","kr":"Kontaktu"}'::jsonb, '/contact', 1 where not exists (select 1 from public.nav_items where menu = 'header' and href = '/contact');
