insert into public.faqs (question, answer, sort) select '{"en":"How does IClangues teaching work?"}'::jsonb, '{"en":"Every class is live with a native speaker — online over Zoom or in person in Cabo Verde. We focus on real conversation from day one, not grammar drills, and weave in culture, music and everyday expressions."}'::jsonb, 0 where not exists (select 1 from public.faqs where question->>'en' = 'How does IClangues teaching work?');
insert into public.faqs (question, answer, sort) select '{"en":"Which languages can I learn?"}'::jsonb, '{"en":"Kriolu (Cape Verdean Creole), English, French, Spanish and Portuguese — all levels from absolute beginner (A1) to near-native (C2)."}'::jsonb, 1 where not exists (select 1 from public.faqs where question->>'en' = 'Which languages can I learn?');
insert into public.faqs (question, answer, sort) select '{"en":"Do I get a certificate?"}'::jsonb, '{"en":"Yes. You receive a certificate at the completion of each level, mapped to the CEFR framework (A1–C2)."}'::jsonb, 2 where not exists (select 1 from public.faqs where question->>'en' = 'Do I get a certificate?');
insert into public.faqs (question, answer, sort) select '{"en":"Can I try before I commit?"}'::jsonb, '{"en":"Absolutely. Take the free placement test and a free trial group lesson — no card required, no commitment."}'::jsonb, 3 where not exists (select 1 from public.faqs where question->>'en' = 'Can I try before I commit?');
insert into public.faqs (question, answer, sort) select '{"en":"Do I need an account?"}'::jsonb, '{"en":"You can browse freely. Create a free account to save courses, track progress and book lessons from your dashboard."}'::jsonb, 4 where not exists (select 1 from public.faqs where question->>'en' = 'Do I need an account?');
